        tree = ast.parse(expression.strip(), mode="eval")
    except SyntaxError as exc:
        raise ValueError("invalid expression") from exc
    return float(_evaluate(tree))

import ast
import operator

_MAX_EXPRESSION_LENGTH = 200
_MAX_EXPONENT = 1000
_MAX_MAGNITUDE = 10**300
_MAX_DEPTH = 50

_BINARY_OPERATORS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}
_UNARY_OPERATORS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


def _check_number(value):
    '''Return value if it is a real number of bounded size, else raise ValueError.'''
    if not isinstance(value, (int, float)) or abs(value) > _MAX_MAGNITUDE:
        raise ValueError('result of expression is out of range')
    return value


def _evaluate_node(node: ast.AST, depth: int = 0) -> float:
    '''Recursively evaluate a whitelisted AST node.

    Raises ValueError for any node type outside the arithmetic subset, for
    excessive nesting, for oversized exponents and for out-of-range results.
    '''
    if depth > _MAX_DEPTH:
        raise ValueError('expression is nested too deeply')
    if isinstance(node, ast.Expression):
        return _evaluate_node(node.body, depth + 1)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
        return _check_number(node.value)
    if isinstance(node, ast.BinOp) and type(node.op) in _BINARY_OPERATORS:
        left = _evaluate_node(node.left, depth + 1)
        right = _evaluate_node(node.right, depth + 1)
        if isinstance(node.op, ast.Pow) and abs(right) > _MAX_EXPONENT:
            raise ValueError('exponent is too large')
        return _check_number(_BINARY_OPERATORS[type(node.op)](left, right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in _UNARY_OPERATORS:
        operand = _evaluate_node(node.operand, depth + 1)
        return _check_number(_UNARY_OPERATORS[type(node.op)](operand))
    raise ValueError('unsupported element in expression: ' + type(node).__name__)


def calculate(expression: str) -> float:
    '''Evaluate an arithmetic expression such as `2 * (3 + 4)` without using eval.

    Only numeric literals, parentheses, unary + and -, and the binary operators
    + - * / // % ** are accepted. The input length, nesting depth, exponent size
    and result magnitude are limited so that a hostile expression cannot
    exhaust CPU or memory.

    Raises:
        ValueError: if the text is not a valid or supported arithmetic expression,
            or exceeds one of the limits.
        ZeroDivisionError: if the expression divides by zero.
    '''
    if len(expression) > _MAX_EXPRESSION_LENGTH:
        raise ValueError('expression is too long')
    try:
        tree = ast.parse(expression.strip(), mode='eval')
    except (SyntaxError, RecursionError) as exc:
        raise ValueError('invalid arithmetic expression: ' + repr(expression)) from exc
    try:
        return float(_evaluate_node(tree))
    except OverflowError as exc:
        raise ValueError('result of expression is out of range') from exc

